pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 amount, uint256 warpTime) public {
        // Keep the domain wide: any amount (including wrong ones) and any future timestamp.
        uint256 ts = 1 + bound(warpTime, 0, type(uint48).max);
        vm.warp(ts);

        uint256 before = c.pastBlockTime();

        // Drive c through its (anonymous) fallback with a fuzzed msg.value,
        // observing success/reversion via the low-level call's boolean.
        vm.deal(address(this), amount);
        (bool ok, ) = address(c).call{value: amount}("");

        // General rule: pastBlockTime may only change as the result of a
        // SUCCESSFUL call. Any reverting call (e.g. msg.value != 10 ether,
        // or timestamp not strictly greater) must leave it unchanged.
        if (!ok) {
            assertEq(c.pastBlockTime(), before);
        } else {
            assertTrue(c.pastBlockTime() == ts);
        }
    }
}

