pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint64 t, address actor) public {
        vm.assume(t > 1);
        vm.assume(actor != address(c) && actor != address(this));
        vm.warp(t);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool firstOk,) = address(c).call{value: 10 ether}("");
        assertTrue(firstOk);
        // A second call in the SAME block/timestamp must revert: pastBlockTime == t,
        // so `require(block.timestamp > pastBlockTime)` fails. The mutant stored
        // t-1, so it wrongly accepts the second call at timestamp t.
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool secondOk,) = address(c).call{value: 10 ether}("");
        assertTrue(!secondOk, "second same-timestamp call must revert");
    }
}

